def note_text(title: str, paragraphs: list[str]) -> str:
    return "---\ntitle: " + title + "\n---\n\n" + "\n\n".join(paragraphs) + "\n"


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    for name, title, paragraphs in NOTES:
        (OUT / name).write_text(
            note_text(title, paragraphs), encoding="utf-8", newline="\n"
        )
    print(f"generated: {len(NOTES)} md in {OUT}")


if __name__ == "__main__":
    main()
